<script setup>
import {ref,computed,watch} from 'vue'

import HelpTip from '../shared/components/HelpTip.vue'
import {toast} from '../shared/composables/toast.js'
const props=defineProps({service:String,caseId:Number,snapshotId:Number,disabled:Boolean})
const rows=ref([]),loading=ref(false),onlyPending=ref(true),detail=ref(null),review=ref(null),note=ref(''),saving=ref(false)
const pending=computed(()=>rows.value.filter(r=>r.state==='needs_review').length),visible=computed(()=>onlyPending.value?rows.value.filter(r=>['needs_review','association_needed'].includes(r.state)):rows.value)
const labels={needs_review:'待复核',reviewed:'已复核',current:'未变化',association_needed:'关联待确认'},kindLabels={modified:'接口修改',removed:'接口移除',added:'新增接口',unchanged:'未变化'}
let epoch=0
async function load(){const n=++epoch;if(!props.service)return;loading.value=true;try{const q=new URLSearchParams({service:props.service,...(props.caseId?{case_id:props.caseId}:{}),...(props.snapshotId?{snapshot_id:props.snapshotId}:{})}),r=await fetch('api/api-testing/document-impacts?'+q),v=await r.json();if(!r.ok)throw Error(v.error||'读取文档影响失败');if(n===epoch)rows.value=v}catch(e){toast(e.message,'error')}finally{if(n===epoch)loading.value=false}}
watch(()=>[props.service,props.caseId,props.snapshotId],load,{immediate:true})
async function save(){if(saving.value)return false;if(!note.value.trim()){toast('请填写复核说明','warning');return false}saving.value=true;try{const r=await fetch('api/api-testing/cases/'+review.value.case_id+'/document-review?service='+encodeURIComponent(props.service),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision:review.value.case_revision,step_index:review.value.step_index,snapshot_id:review.value.snapshot_id,note:note.value})}),v=await r.json();if(!r.ok)throw Error(v.error||'复核失败');review.value=null;await load();toast('已记录复核，不改变请求、断言或执行结果','success')}catch(e){toast(e.message,'error')}finally{saving.value=false}return false}
function openCase(r){const hash='#/test-cases?'+new URLSearchParams({service:props.service,case:r.case_id});if(window.parent!==window)window.parent.postMessage({type:'workspace.open',plugin:'api-center',hash},location.origin);else window.open(location.pathname+hash,'_blank','noopener')}
const pretty=v=>v===undefined?'未定义':String(v)

import {ref as _viewRef} from 'vue'
const _view1=_viewRef(props.caseId?[]:['impact'])
const _view2=_viewRef(1)
const _view3=_viewRef(1)


import {Accordion,AccordionContent,AccordionItem,AccordionTrigger,Badge,Button,Dialog,DialogContent,DialogDescription,DialogFooter,DialogHeader,DialogTitle,Empty,EmptyContent,EmptyDescription,EmptyHeader,Field,FieldDescription,FieldError,FieldLabel,Pagination,PaginationContent,PaginationNext,PaginationPrevious,Sheet,SheetContent,SheetDescription,SheetFooter,SheetHeader,SheetTitle,Spinner,Switch,Table,TableBody,TableCell,TableHead,TableHeader,TableRow,Textarea} from '../shared/shadcn-ui.js'
</script>
<template><Accordion class="document-impact" type="multiple" :model-value="(_view1||[]).map(String)" @update:model-value="_view1=$event"><AccordionItem :value="String(&quot;impact&quot;)"><AccordionTrigger>详细设置</AccordionTrigger><AccordionContent force-mount v-show="!(!(_view1||[]).map(String).includes(String(&quot;impact&quot;)))"><template #extra><HelpTip text="按步骤关联的基线与同环境最新文档比较。复核绑定用例修订与文档快照；任一再次变化都会重新提示。复核不代表自动测试通过。"/></template><div class="impact-toolbar flex flex-wrap items-center gap-2"><Switch v-model="onlyPending" checked-text="仅待处理" unchecked-text="查看全部"/><Button @click="load" variant="outline" size="default" type="button" :disabled="(loading)"><Spinner v-if="loading"/>刷新</Button></div><div class="min-w-0 max-w-full"><div v-if="loading" class="flex items-center gap-2 py-2" role="status"><Spinner/>正在读取</div><div class="max-w-full overflow-auto rounded-lg border" :style="{maxHeight:({x:750}).y?({x:750}).y+'px':undefined}"><Table class="table-fixed min-w-[var(--table-min-width)]" :style="{'--table-min-width':(({x:750}).x||({x:750}).minWidth||635)+'px'}"><TableHeader><TableRow><TableHead>用例 / 步骤</TableHead><TableHead :style="{width:(160)+'px'}">文档基线 → 当前</TableHead><TableHead :style="{width:(125)+'px'}">状态</TableHead><TableHead :style="{width:(200)+'px'}">操作</TableHead></TableRow></TableHeader><TableBody><template v-for="(record,rowIndex) in (visible||[]).slice((_view2-1)*(({pageSize:10}).pageSize||10),_view2*(({pageSize:10}).pageSize||10))" :key="typeof ('id')==='function'?('id')(record):record['id']??rowIndex"><TableRow><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><Button @click="openCase(record)" class="impact-name" variant="ghost" size="default" type="button">TC-{{record.case_id}} · {{record.case_name}}</Button><div>{{record.step_index+1}}. {{record.step_name}}</div></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]">{{record.environment||'历史'}} · #{{record.baseline_id}} → #{{record.snapshot_id}}</template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><Badge :variant="(record.state==='needs_review'?'orange':record.state==='reviewed'?'green':undefined)==='red'?'destructive':'secondary'">{{labels[record.state]}}</Badge></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><Button @click="detail=record" variant="ghost" size="default" type="button">查看差异</Button><Button v-if="record.can_review" @click="review=record;note=''" variant="ghost" size="default" type="button" :disabled="(disabled)">确认复核</Button></template></div></TableCell></TableRow></template><TableRow v-if="!(visible||[]).length"><TableCell :colspan="4"><Empty><EmptyHeader><EmptyDescription>{{onlyPending?'暂无待处理的文档影响':'暂无关联；可在用例步骤中关联文档接口'}}</EmptyDescription></EmptyHeader></Empty></TableCell></TableRow></TableBody></Table></div><div class="flex flex-wrap items-center justify-end gap-3 py-4"><span class="mr-auto text-sm text-muted-foreground">共 {{(visible||[]).length}} 项</span><Pagination class="mx-0 w-auto" :page="_view2" :total="(visible||[]).length" :items-per-page="({pageSize:10}).pageSize||10" @update:page="_view2=$event;"><PaginationContent><PaginationPrevious/><span class="px-2 text-sm">{{_view2}} / {{Math.max(1,Math.ceil(((visible||[]).length)/(({pageSize:10}).pageSize||10)))}}</span><PaginationNext/></PaginationContent></Pagination></div></div></AccordionContent></AccordionItem></Accordion><Sheet :open="!!detail" @update:open="async v=>{if(!v){detail=null}}"><SheetContent class="data-[side=right]:w-full gap-0 overflow-hidden p-0 data-[side=right]:sm:max-w-[var(--editor-width)]" :class="false?'inset-0 h-dvh max-h-dvh w-screen max-w-none translate-x-0 translate-y-0 rounded-none sm:max-w-none':''" :style="{'--editor-width':typeof ('min(820px,95vw)')==='number'?('min(820px,95vw)')+'px':('min(820px,95vw)')}" :show-close-button="true" @interact-outside="e=>{e.preventDefault()}"><SheetHeader class="shrink-0 border-b p-5 pr-12"><SheetTitle>文档变更详情</SheetTitle><SheetDescription class="sr-only">详情与操作</SheetDescription></SheetHeader><div class="min-h-0 flex-1 overflow-auto p-5"><template v-if="detail"><dl class="grid min-w-0 gap-4 sm:grid-cols-2"><div class="min-w-0 space-y-1"><dt class="text-sm text-muted-foreground">接口</dt><dd class="min-w-0 break-words">{{detail.operation_id||'尚未明确关联'}}</dd></div><div class="min-w-0 space-y-1"><dt class="text-sm text-muted-foreground">关联方式</dt><dd class="min-w-0 break-words">{{detail.inferred?'历史用例按方法与路径唯一匹配':'步骤明确关联'}}</dd></div><div class="min-w-0 space-y-1"><dt class="text-sm text-muted-foreground">变化</dt><dd class="min-w-0 break-words">{{kindLabels[detail.kind]||detail.kind||'待确认'}}</dd></div><div class="min-w-0 space-y-1"><dt class="text-sm text-muted-foreground">说明</dt><dd class="min-w-0 break-words">{{detail.message}}</dd></div><div v-if="detail.note" class="min-w-0 space-y-1"><dt class="text-sm text-muted-foreground">复核说明</dt><dd class="min-w-0 break-words">{{detail.reviewed_by}} · {{detail.note}}</dd></div></dl><Badge v-if="detail.truncated" :variant="(&quot;orange&quot;)==='red'?'destructive':'secondary'">差异已截断，请核对原始文档</Badge><div class="min-w-0 max-w-full"><div class="max-w-full overflow-auto rounded-lg border" :style="{maxHeight:({}).y?({}).y+'px':undefined}"><Table class="table-fixed min-w-[var(--table-min-width)]" :style="{'--table-min-width':(({}).x||({}).minWidth||450)+'px'}"><TableHeader><TableRow><TableHead>字段</TableHead><TableHead>原值</TableHead><TableHead>新值</TableHead></TableRow></TableHeader><TableBody><template v-for="(record,rowIndex) in (detail.fields||[]||[]).slice((_view3-1)*(({pageSize:10}).pageSize||10),_view3*(({pageSize:10}).pageSize||10))" :key="typeof ('id')==='function'?('id')(record):record['id']??rowIndex"><TableRow><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}">{{record["path"]}}</div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><pre>{{record.before_present?pretty(record.before):'未定义'}}</pre></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><pre>{{record.after_present?pretty(record.after):'未定义'}}</pre></template></div></TableCell></TableRow></template><TableRow v-if="!(detail.fields||[]||[]).length"><TableCell :colspan="3"><Empty><EmptyHeader><EmptyDescription>暂无数据</EmptyDescription></EmptyHeader></Empty></TableCell></TableRow></TableBody></Table></div><div class="flex flex-wrap items-center justify-end gap-3 py-4"><span class="mr-auto text-sm text-muted-foreground">共 {{(detail.fields||[]||[]).length}} 项</span><Pagination class="mx-0 w-auto" :page="_view3" :total="(detail.fields||[]||[]).length" :items-per-page="({pageSize:10}).pageSize||10" @update:page="_view3=$event;"><PaginationContent><PaginationPrevious/><span class="px-2 text-sm">{{_view3}} / {{Math.max(1,Math.ceil(((detail.fields||[]||[]).length)/(({pageSize:10}).pageSize||10)))}}</span><PaginationNext/></PaginationContent></Pagination></div></div></template></div></SheetContent></Sheet><Dialog :open="!!review" @update:open="async v=>{if(!v){review=null}}"><DialogContent class="flex max-h-[92dvh] flex-col gap-0 overflow-hidden p-0 sm:max-w-[var(--editor-width)]" :class="false?'inset-0 h-dvh max-h-dvh w-screen max-w-none translate-x-0 translate-y-0 rounded-none sm:max-w-none':''" :style="{'--editor-width':typeof (560)==='number'?(560)+'px':(560)}" :show-close-button="!saving" @interact-outside="e=>{if(!(!saving))e.preventDefault()}"><DialogHeader class="shrink-0 border-b p-5 pr-12"><DialogTitle>确认已复核文档变更</DialogTitle><DialogDescription class="sr-only">详情与操作</DialogDescription></DialogHeader><div class="min-h-0 flex-1 overflow-auto p-5"><fieldset class="min-w-0 space-y-5" ><Field><FieldLabel>复核说明 <span class="text-destructive">*</span></FieldLabel><Textarea v-model="note" placeholder="说明已核对的请求和断言，以及是否需要调整用例" aria-label="文档复核说明" :maxlength="2000" :rows="({minRows:4,maxRows:8}).minRows||4"/></Field></fieldset></div><DialogFooter class="shrink-0 flex-wrap border-t p-4"><Button variant="outline" @click="async()=>{review=null}">取消</Button><Button :disabled="saving" @click="async()=>{if(await (save)()!==false){}}"><Spinner v-if="saving"/>确认</Button></DialogFooter></DialogContent></Dialog></template>
<style scoped>.document-impact{margin:16px 0 24px}.impact-toolbar{margin-bottom:16px}.impact-name{white-space:normal;text-align:left;justify-content:flex-start}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:240px;overflow:auto}</style>
